// A continuous city-block ribbon: the corners are authored circular arcs,
// not a perturbed oval. Heights belong to districts and connect over the
// intervening streets; the rooftop fork is generated by Track's normal fork.
const blocks = [
  [-600, 90, 0, 140],
  [1100, 90, 0, 140],
  [1100, 145, 650, 130],
  [850, 145, 650, 85],
  [900, 145, 880, 100],
  [1200, 145, 880, 150],
  [1200, 190, 1800, 150],
  [-100, 70, 1800, 130],
  [-100, 45, 1250, 110],
  [-750, 45, 1250, 110],
  [-750, 85, 1850, 135],
  [-1450, 115, 1850, 150],
  [-1450, 115, 850, 140],
  [-800, 75, 850, 110],
  [-800, 45, 350, 110],
  [-1450, 45, 350, 130],
  [-1450, 70, -450, 150],
  [-600, 90, -450, 140],
];

function cityRibbon() {
  const corners = blocks.map(([x, y, z, radius], i) => {
    const before = blocks[(i + blocks.length - 1) % blocks.length];
    const after = blocks[(i + 1) % blocks.length];
    const beforeLength = Math.hypot(x - before[0], z - before[2]);
    const afterLength = Math.hypot(after[0] - x, after[2] - z);
    const incoming = [
      (x - before[0]) / beforeLength,
      (z - before[2]) / beforeLength,
    ];
    const outgoing = [
      (after[0] - x) / afterLength,
      (after[2] - z) / afterLength,
    ];
    const turn = Math.atan2(
      incoming[0] * outgoing[1] - incoming[1] * outgoing[0],
      incoming[0] * outgoing[0] + incoming[1] * outgoing[1],
    );
    const trim = radius * Math.tan(Math.abs(turn) / 2);
    const entry = [x - incoming[0] * trim, y, z - incoming[1] * trim];
    const exit = [x + outgoing[0] * trim, y, z + outgoing[1] * trim];
    const center = [
      entry[0] - incoming[1] * Math.sign(turn) * radius,
      entry[2] + incoming[0] * Math.sign(turn) * radius,
    ];
    const start = Math.atan2(entry[2] - center[1], entry[0] - center[0]);
    return { entry, exit, center, start, turn, radius };
  });
  const points = [];
  for (let i = 0; i < corners.length; i++) {
    const c = corners[i];
    const arcSteps = Math.ceil(Math.abs(c.turn) / (Math.PI / 12));
    for (let j = 0; j <= arcSteps; j++) {
      const a = c.start + (c.turn * j) / arcSteps;
      points.push([
        c.center[0] + c.radius * Math.cos(a),
        c.entry[1],
        c.center[1] + c.radius * Math.sin(a),
      ]);
    }
    const next = corners[(i + 1) % corners.length].entry;
    const distance = Math.hypot(next[0] - c.exit[0], next[2] - c.exit[2]);
    const steps = Math.ceil(distance / 90);
    for (let j = 1; j < steps; j++) {
      const t = j / steps;
      const smooth = t * t * (3 - 2 * t);
      points.push([
        c.exit[0] + (next[0] - c.exit[0]) * t,
        c.exit[1] + (next[1] - c.exit[1]) * smooth,
        c.exit[2] + (next[2] - c.exit[2]) * t,
      ]);
    }
  }
  // Put the grid halfway along the longest level boulevard, not on an apex.
  const grid = points.findIndex(
    ([x, , z]) => x > 150 && x < 210 && Math.abs(z) < 1e-6,
  );
  if (grid < 0) throw new Error("VESPER grid station missing");
  return [...points.slice(grid), ...points.slice(0, grid)];
}

